const crypto = require\('crypto'\);
const Database = require\('better-sqlite3'\);
const db = new Database\('./backend/treasury.db'\);
const DEV_KEY = crypto.createHash\('sha256'\).update\('treasury-dev-key-not-for-production'\).digest\(\);
function decrypt\(b64\) {
  const d = Buffer.from\(b64, 'base64'\);
  const decipher = crypto.createDecipheriv\('aes-256-gcm', DEV_KEY, d.subarray\(0,16\)\);
  decipher.setAuthTag\(d.subarray\(16,32\)\);
  return Buffer.concat\([decipher.update\(d.subarray\(32\)\), decipher.final\(\)]\).toString\('utf8'\);
}

// Find Mexico account and add it to payroll 'to'
const mexico = db.prepare\(\\"SELECT id FROM accounts WHERE name LIKE '%Mexico%8375%'\\"\).get\(\);
if \(mexico\) {
  db.prepare\(\\"INSERT INTO group_accounts \(id, group_id, account_id, direction, funding_type, added_by, created_at\) VALUES \(?, 'grp-payroll', ?, 'to', 'both', 'admin-001', datetime\('now'\)\)\\"\).run\(
    crypto.randomBytes\(16\).toString\('hex'\), mexico.id
  \);
  console.log\('Added Mexico account to Payroll destinations'\);
} else {
  console.log\('Mexico account not found'\);
}

// Verify payroll assignments
const payrollAccts = db.prepare\(\\"SELECT ga.direction, a.name FROM group_accounts ga JOIN accounts a ON a.id = ga.account_id WHERE ga.group_id = 'grp-payroll'\\"\).all\(\);
console.log\('Payroll accounts:'\);
for \(const pa of payrollAccts\) {
  console.log\('  ', pa.direction, '-', pa.name\);
}
db.close\(\);
")
